// Count today's activity and list tomorrow's schedule.
const today = $now.toFormat('yyyy-MM-dd');
const tomorrow = $now.plus({ days: 1 }).toFormat('yyyy-MM-dd');
const rows = name => $(name).all().map(i => i.json).filter(r => r.id); // skip the empty placeholder item
const bookings = rows('Read Bookings sheet');
const inquiries = rows('Read Inquiries sheet');

const todayMsgs = inquiries.filter(r => String(r.created_at).startsWith(today));
const count = intent => todayMsgs.filter(r => r.intent === intent).length;
const newBookings = bookings.filter(r => String(r.created_at).startsWith(today));
const complaints = todayMsgs.filter(r => r.intent === 'complaint');
const urgent = todayMsgs.filter(r => r.urgency === 'high' && r.intent !== 'complaint');
const tmrw = bookings
  .filter(r => r.date === tomorrow && !/cancel/i.test(r.status))
  .sort((a, b) => String(a.time).localeCompare(String(b.time)));

const lines = [
  `📊 Daily summary – ${$now.toFormat('cccc d LLL yyyy')}`,
  '',
  `Today: ${todayMsgs.length} message(s)`,
  `• New bookings: ${newBookings.length}`,
  `• Questions: ${count('question')}`,
  `• Complaints: ${complaints.length}`,
  `• Urgent cases: ${urgent.length}`,
  `• Other/spam: ${count('other')}`,
];
if (complaints.length) lines.push('', '⚠️ Complaints:', ...complaints.map(r => `• ${r.name || 'Unknown'} (${r.phone || r.email || '-'}): ${r.summary}`));
if (urgent.length) lines.push('', '🚨 Urgent:', ...urgent.map(r => `• ${r.name || 'Unknown'} (${r.phone || '-'}): ${r.summary}`));
lines.push('', `📅 Tomorrow (${tomorrow}): ${tmrw.length} appointment(s)`);
lines.push(...(tmrw.length ? tmrw.map(r => `• ${r.time} – ${r.name || 'Unknown'} (${r.phone || '-'}) [${r.status}]`) : ['• No appointments']));
const pending = tmrw.filter(r => !/confirm/i.test(r.status)).length;
if (pending) lines.push('', `👉 ${pending} of tomorrow's booking(s) still Pending – confirm them in the sheet.`);

return [{ json: { text: lines.join('\n') } }];
